import { COACH } from '../coach.config';
import { isRegressing, type Exposure } from './progression';
import { addDays, toDay } from './weight';

// Readiness, early deload and pain rules (spec §6). The messages for these are hard-coded copy in
// the UI, never generated by the LLM.

const R = COACH.training.readiness;
const P = COACH.training.pain;

export interface Readiness { date: string; sleepHours: number | null; energy: number | null; soreness: number | null }

/** Low readiness: short sleep, low energy or high soreness. */
export const isLowReadiness = (r: Omit<Readiness, 'date'>) =>
  (r.sleepHours != null && r.sleepHours < R.lowSleepHours)
  || (r.energy != null && r.energy <= R.lowEnergyAtMost)
  || (r.soreness != null && r.soreness >= R.highSorenessAtLeast);

const lowDaysInLastWeek = (entries: readonly Readiness[], today: string) => {
  const from = toDay(addDays(today, -6));
  return entries.filter((e) => toDay(e.date) >= from && toDay(e.date) <= toDay(today) && isLowReadiness(e)).length;
};

/** Low readiness on most days of the last week → time for an early deload. */
export const readinessDeloadDue = (entries: readonly Readiness[], today: string) => lowDaysInLastWeek(entries, today) >= R.lowDaysForDeload;

/** Recovery isn't good enough to add sets this week (spec §6: ramp "when recovery is good"). */
export const holdRamp = (entries: readonly Readiness[], today: string) => lowDaysInLastWeek(entries, today) >= R.holdRampLowDays;

/** Early deload (spec §6): 2+ main lifts regressing for 2 sessions, or a week of low readiness. */
export function earlyDeloadReason(o: {
  mainLifts: readonly (readonly Exposure[])[];
  readiness: readonly Readiness[];
  today: string;
}): 'regression' | 'readiness' | null {
  const regressing = o.mainLifts.filter((h) => isRegressing(h)).length;
  if (regressing >= COACH.training.earlyDeload.regressingMainLifts) return 'regression';
  if (readinessDeloadDue(o.readiness, o.today)) return 'readiness';
  return null;
}

// ─── Pain ─────────────────────────────────────────────────────────────────────────────────
export const RED_FLAGS = ['chest_pain', 'dizziness', 'numbness', 'sharp_joint'] as const;
export type RedFlag = (typeof RED_FLAGS)[number];

/** Pain ≥ 4/10 or sharp: stop this exercise, offer a regression/substitute, exclude it. */
export const mustStop = (level: number, sharp: boolean) => sharp || level >= P.stopAt;

export interface PainReport { date: string; area: string; level: number }

/** Repeated pain in one body area within the window → recommend a physiotherapist. */
export function recurringPain(reports: readonly PainReport[], area: string, today: string): boolean {
  const from = toDay(addDays(today, -P.recurringWindowDays));
  return reports.filter((r) => r.area === area && r.level > 0 && toDay(r.date) >= from).length >= P.recurringReports;
}
